// Release builds sign with the dedicated release keystore, never the debug key.
// android/ is regenerated by prebuild, so this patches app/build.gradle each time.
//
// Values come from Gradle properties (~/.gradle/gradle.properties, outside the repo)
// or the same-named environment variables:
//   MUDI_RELEASE_STORE_FILE      absolute path to the .jks
//   MUDI_RELEASE_STORE_PASSWORD
//   MUDI_RELEASE_KEY_ALIAS
//   MUDI_RELEASE_KEY_PASSWORD
// A release build without them fails instead of falling back to the debug key.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// mudi-dokan release signing';

const SIGNING = `
        release { ${MARKER}
            def mudi = { String k -> (findProperty(k) ?: System.getenv(k)) as String }
            if (mudi('MUDI_RELEASE_STORE_FILE')) {
                storeFile file(mudi('MUDI_RELEASE_STORE_FILE'))
                storePassword mudi('MUDI_RELEASE_STORE_PASSWORD')
                keyAlias mudi('MUDI_RELEASE_KEY_ALIAS')
                keyPassword mudi('MUDI_RELEASE_KEY_PASSWORD')
            }
        }`;

const GUARD = `
${MARKER}: refuse to build a release APK with no release key
gradle.taskGraph.whenReady { graph ->
    def wantsRelease = graph.allTasks.any { it.project == project && it.name ==~ /(assemble|bundle|package)Release/ }
    def storeFile = findProperty('MUDI_RELEASE_STORE_FILE') ?: System.getenv('MUDI_RELEASE_STORE_FILE')
    if (wantsRelease && (!storeFile || !file(storeFile).exists())) {
        throw new GradleException("Release keystore not found. Set MUDI_RELEASE_STORE_FILE (+ passwords, alias) in ~/.gradle/gradle.properties; see CLAUDE.md.")
    }
}
`;

function patch(src) {
  if (src.includes(MARKER)) return src;
  // add a release signing config next to the debug one
  const sc = src.indexOf('signingConfigs {');
  if (sc < 0) throw new Error('withReleaseSigning: no signingConfigs block in app/build.gradle');
  const at = sc + 'signingConfigs {'.length;
  let out = src.slice(0, at) + SIGNING + src.slice(at);
  // buildTypes.release: signingConfigs.debug → signingConfigs.release
  const bt = out.indexOf('buildTypes {');
  const rel = out.indexOf('release {', bt);
  const use = out.indexOf('signingConfig signingConfigs.debug', rel);
  if (bt < 0 || rel < 0 || use < 0) throw new Error('withReleaseSigning: buildTypes.release signingConfig not found');
  out = out.slice(0, use) + 'signingConfig signingConfigs.release' + out.slice(use + 'signingConfig signingConfigs.debug'.length);
  return out + GUARD;
}

module.exports = (config) =>
  withAppBuildGradle(config, (c) => {
    c.modResults.contents = patch(c.modResults.contents);
    return c;
  });
module.exports.patch = patch;
